import numpy as np
A = acts(X)
def downstream(resid_mid, override=None):
    pre = resid_mid@Win; post=np.maximum(pre,0); mo=post@Wout
    return (resid_mid+mo)@WU
P0 = ((X[:,0]*X[:,1])%113)
base = (A['resid_post']@WU).argmax(1)
def test_site(site, ks=(1,2,3,5,7,9,12,20,40)):
    V = A[site]; mu=V.mean(0); U,S,Vt=np.linalg.svd(V-mu, full_matrices=False)
    out={}
    for k in ks:
        rec = mu + (V-mu)@Vt[:k].T@Vt[:k]
        if site in ('resid_mid',):
            lg = downstream(rec)
        elif site in ('mlp_out',):
            lg = (A['resid_mid']+rec)@WU
        elif site in ('resid_post',):
            lg = rec@WU
        else:
            lg=None
        if lg is not None:
            out[k]=round((lg.argmax(1)==base).mean(),3)
    return out
print("resid_mid", test_site('resid_mid'))
print("resid_post", test_site('resid_post'))
print("mlp_out", test_site('mlp_out'))
